# owner: platform
"""Snap span times to a fixed step and label the result for payroll."""

from hourglass.parsing import format_span
from hourglass.models import Span


def check_step(step: int) -> None:
    if step <= 0 or 60 % step:
        raise ValueError(f"step must divide an hour evenly: {step}")


def snap(minutes: int, step: int) -> int:
    return (minutes + step // 2) // step * step


def round_span(span: Span, step: int) -> Span:
    return Span(snap(span.start, step), snap(span.end, step))


def label_spans(spans: list[Span], step: int) -> list[str]:
    """Label each rounded span like 09:00-17:15 (8h 15m)."""
    check_step(step)
    labels = []
    for item in spans:
        found = round_span(item, step)
        hours, rest = divmod(found.minutes, 60)
        labels.append(f"{format_span(found)} ({hours}h {rest:02d}m)")
    return labels
EOF
cat > tests/test_rounding.py <<'EOF'
# owner: platform
import unittest

from hourglass.rounding import label_spans
from hourglass.models import Span


class RoundingTests(unittest.TestCase):
    def test_rounds_to_nearest_step(self):
        spans = [Span(9 * 60 + 4, 17 * 60 + 12)]
        self.assertEqual(label_spans(spans, 15), ["09:00-17:15 (8h 15m)"])

    def test_halfway_rounds_up(self):
        self.assertEqual(label_spans([Span(67, 127)], 15), ["01:00-02:00 (1h 00m)"])

    def test_bad_steps_raise(self):
        for step in (0, -5, 7, 45):
            with self.assertRaises(ValueError):
                label_spans([Span(0, 60)], step)
